//! Official CityGML 2.0 XSD validation of generated bytes, shared by the test binaries.
use std::io::Write;

/// Validates `bytes` against the cached official schemas. CI sets
/// `CADKIT_REQUIRE_GML_XSD`, so a missing cache or validator fails there; elsewhere the
/// check is skipped when either is unavailable.
pub fn validate_xsd_if_cached(bytes: &[u8]) {
    let required = std::env::var_os("CADKIT_REQUIRE_GML_XSD").is_some();
    // Optional local Python/lxml validator: stdin is XML and exit status is the
    // only diagnostic, so private values cannot escape through schema errors.
    if let Some(script) = std::env::var_os("CADKIT_XSD_VALIDATOR_SCRIPT") {
        let mut child = std::process::Command::new("python")
            .arg(script)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .unwrap();
        child.stdin.take().unwrap().write_all(bytes).unwrap();
        assert!(
            child.wait().unwrap().success(),
            "official CityGML XSD validation failed"
        );
        return;
    }
    let cache = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../corpus/public/citygml-schemas");
    if !cache.join("profile.xsd").exists() {
        assert!(
            !required,
            "required official CityGML schema cache is missing; run scripts/validate-citygml.py --fetch"
        );
        return;
    }
    let child = std::process::Command::new("xmllint")
        .args(["--nonet", "--noout", "--schema"])
        .arg(cache.join("profile.xsd"))
        .arg("-")
        .env("XML_CATALOG_FILES", cache.join("catalog.xml"))
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::piped())
        .spawn();
    // A fetched cache without xmllint (a developer machine) is not a failure.
    let Ok(mut child) = child else {
        assert!(
            !required,
            "xmllint is required for official CityGML XSD validation"
        );
        return;
    };
    child.stdin.take().unwrap().write_all(bytes).unwrap();
    let output = child.wait_with_output().unwrap();
    // Report only the exit status so XSD error messages cannot leak private values.
    assert!(
        output.status.success(),
        "official CityGML XSD validation failed"
    );
}
